package extractor

import (
	"io/fs"
	"path/filepath"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/entities"
)

// Extractor is the main No-LLM entity extractor.
type Extractor struct {
	root string
}

func New(root string) *Extractor {
	return &Extractor{root: root}
}

// Run executes the extraction process over the repository.
func (e *Extractor) Run() ([]entities.Entity, error) {
	var all []entities.Entity

	// 1. Extract from config.yaml if exists
	ruleEntities, err := ExtractFromRules(filepath.Join(e.root, "config.yaml"))
	if err == nil && ruleEntities != nil {
		all = append(all, ruleEntities...)
	}

	// 2. Walk directory
	err = Walk(e.root, func(path string, d fs.DirEntry) error {
		if d.IsDir() {
			return nil
		}

		// Config entities
		cfgEntities, err := ParseConfig(path)
		if err == nil && cfgEntities != nil {
			all = append(all, cfgEntities...)
		}

		// Symbol entities
		symEntities, err := ExtractSymbols(path)
		if err == nil && symEntities != nil {
			all = append(all, symEntities...)
		}

		// We could also emit file entities themselves
		rel, _ := filepath.Rel(e.root, path)
		all = append(all, entities.Entity{
			ID:   "file:" + rel,
			Kind: entities.KindFile,
			Name: rel,
		})

		return nil
	})

	if err != nil {
		return nil, err
	}

	return all, nil
}
package extractor

import (
	"os"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/entities"
	"gopkg.in/yaml.v3"
)

type ConfigRules struct {
	Rules struct {
		Topics []string `yaml:"topics"`
		Tools  []string `yaml:"tools"`
		Errors []string `yaml:"errors"`
	} `yaml:"rules"`
}

func ExtractFromRules(configPath string) ([]entities.Entity, error) {
	data, err := os.ReadFile(configPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil // Return empty if no config.yaml
		}
		return nil, err
	}

	var cfg ConfigRules
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return nil, err
	}

	var extracted []entities.Entity
	for _, topic := range cfg.Rules.Topics {
		extracted = append(extracted, entities.Entity{
			ID:   "topic:" + topic,
			Kind: entities.KindTopic,
			Name: topic,
		})
	}
	for _, tool := range cfg.Rules.Tools {
		extracted = append(extracted, entities.Entity{
			ID:   "tool:" + tool,
			Kind: entities.KindTool,
			Name: tool,
		})
	}
	for _, errItem := range cfg.Rules.Errors {
		extracted = append(extracted, entities.Entity{
			ID:   "error:" + errItem,
			Kind: entities.KindError,
			Name: errItem,
		})
	}
	return extracted, nil
}
package extractor

import (
	"bufio"
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/entities"
)

var funcRegex = regexp.MustCompile(`^[\w\s\*&]+\s+(\w+)\s*\([^)]*\)\s*\{?$`)

func ExtractSymbols(path string) ([]entities.Entity, error) {
	ext := filepath.Ext(path)
	if ext != ".c" && ext != ".cpp" && ext != ".h" && ext != ".hpp" {
		return nil, nil
	}

	// Try ctags first
	if ctagsPath, err := exec.LookPath("ctags"); err == nil {
		cmd := exec.Command(ctagsPath, "-x", "--c-kinds=fp", path)
		out, err := cmd.Output()
		if err == nil {
			var ext []entities.Entity
			scanner := bufio.NewScanner(bytes.NewReader(out))
			for scanner.Scan() {
				parts := strings.Fields(scanner.Text())
				if len(parts) > 0 {
					ext = append(ext, entities.Entity{
						ID:   "symbol:" + parts[0],
						Kind: entities.KindSymbol,
						Name: parts[0],
					})
				}
			}
			return ext, nil
		}
	}

	// Fallback to naive brace-aware scanner
	return fallbackCScanner(path)
}

func fallbackCScanner(path string) ([]entities.Entity, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var extracted []entities.Entity
	scanner := bufio.NewScanner(f)
	braceLevel := 0

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())

		// adjust brace level
		braceLevel += strings.Count(line, "{")
		braceLevel -= strings.Count(line, "}")

		if braceLevel == 0 || (braceLevel == 1 && strings.HasSuffix(line, "{")) {
			// Look for function signatures
			if matches := funcRegex.FindStringSubmatch(line); len(matches) > 1 {
				name := matches[1]
				if name != "if" && name != "for" && name != "while" && name != "switch" {
					extracted = append(extracted, entities.Entity{
						ID:   "symbol:" + name,
						Kind: entities.KindSymbol,
						Name: name,
					})
				}
			}
		}
	}
	return extracted, nil
}

